"""Models generated by image-to-3D (TRELLIS.2, see docs/ART.md), baked into
the game's format in place of the built-in ones.

    blender -b --python tools/generated.py -- crystal

The source of each is a textured GLB in art/generated/. Its faces are sorted
into the game's materials by the colour of their texture (glowing crystal,
snow, stone...), so the shader paints and lights them like the hand-made
models; the model is centred, stood on z = 0 and scaled to its footprint;
and where the game needs several versions (a crystal worn down as it is
mined) they are made from the one model.
"""

import colorsys
import os
import sys

import bmesh
import bpy
from mathutils import Vector

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import export_models as em  # noqa: E402

SRC = "art/generated"


def load(path):
    """Import a GLB into an empty scene as one mesh object."""
    bpy.ops.wm.read_factory_settings(use_empty=True)
    bpy.ops.import_scene.gltf(filepath=os.path.abspath(path))
    objs = [o for o in bpy.context.scene.objects if o.type == "MESH"]
    bpy.ops.object.select_all(action="DESELECT")
    for o in objs:
        o.select_set(True)
    bpy.context.view_layer.objects.active = objs[0]
    if len(objs) > 1:
        bpy.ops.object.join()
    obj = bpy.context.view_layer.objects.active
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    return obj


def deepen(obj, gamma):
    """Darken the texture's midtones (and so saturate it): image-to-3D bakes
    in soft studio light, which reads washed out under the game's sun."""
    mat = obj.material_slots[0].material
    for n in mat.node_tree.nodes:
        if n.type == "TEX_IMAGE" and n.image:
            img = n.image
            px = list(img.pixels[:])
            for i in range(0, len(px), 4):
                px[i] = px[i] ** gamma
                px[i + 1] = px[i + 1] ** gamma
                px[i + 2] = px[i + 2] ** gamma
            img.pixels[:] = px
            return


def texture_pixels(obj):
    """The base-colour texture of the model's first material: (w, h, rgba floats)."""
    img = em.base_image(obj.material_slots[0].material) if obj.material_slots else None
    if img is None:
        raise SystemExit("the model has no base-colour texture")
    return img


def face_colours(obj, img):
    """Each face's colour, from the texture at the middle of its UVs (sRGB 0..1)."""
    w, h, px = img
    uv = obj.data.uv_layers.active.data
    out = []
    for f in obj.data.polygons:
        u = sum(uv[li].uv[0] for li in f.loop_indices) / f.loop_total
        v = sum(uv[li].uv[1] for li in f.loop_indices) / f.loop_total
        x = min(w - 1, max(0, int((u % 1.0) * w)))
        y = min(h - 1, max(0, int((v % 1.0) * h)))
        rgb = px[(y * w + x) * 4:(y * w + x) * 4 + 3]
        out.append(tuple(em.linear_to_srgb(c) for c in rgb))
    return out


def assign(obj, classes, names):
    """Give each face the material named for its class; every material keeps
    the texture, so colours still come from it."""
    base = obj.material_slots[0].material
    obj.data.materials.clear()
    for n in names:
        m = base.copy()
        m.name = n
        obj.data.materials.append(m)
    for f, c in zip(obj.data.polygons, classes):
        f.material_index = c


def normalise(obj, width):
    """Centre on the footprint, stand on z = 0, and scale so the widest side
    across the ground is `width` tiles."""
    lo = Vector([min((obj.matrix_world @ v.co)[i] for v in obj.data.vertices) for i in range(3)])
    hi = Vector([max((obj.matrix_world @ v.co)[i] for v in obj.data.vertices) for i in range(3)])
    s = width / max(hi.x - lo.x, hi.y - lo.y)
    mid = Vector(((lo.x + hi.x) / 2, (lo.y + hi.y) / 2, lo.z))
    for v in obj.data.vertices:
        v.co = (v.co - mid) * s


def decimate(obj, tris):
    n = sum(len(p.vertices) - 2 for p in obj.data.polygons)
    if n > tris:
        m = obj.modifiers.new("decimate", "DECIMATE")
        m.ratio = tris / n
        bpy.context.view_layer.objects.active = obj
        bpy.ops.object.modifier_apply(modifier=m.name)


def bake(name, objs):
    baker = em.PropBaker(objs, Vector((0, 0, 0)), 1.0)
    baker.capture()
    em.write_model(f"{em.OUT_DIR}/{name}.sbm", [baker.encode(name)])
    tris = sum(len(p.vertices) - 2 for o in objs for p in o.data.polygons)
    print(f"{name}: {tris} triangles, {len(baker.colors)} vertices")


def crystal():
    """The crystal cluster on its snowy rock, and its three worn-down
    versions (crystal-0 is mined out: stubs on the rock)."""
    obj = load(f"{SRC}/crystal.glb")
    deepen(obj, 1.6)
    img = texture_pixels(obj)
    cols = face_colours(obj, img)
    # Violet shards shine, their brightest facets glow; white is snow; the
    # rest is rock.
    classes = []
    for r, g, b in cols:
        hue, sat, val = colorsys.rgb_to_hsv(r, g, b)
        if sat > 0.25 and 0.66 < hue < 0.95:
            classes.append(3 if val > 0.8 else 0)
        elif val > 0.72 and sat < 0.18:
            classes.append(1)
        else:
            classes.append(2)
    assign(obj, classes, ["Gloss Crystal", "Snow", "Stone", "Glow Crystal"])
    normalise(obj, 1.25)
    decimate(obj, 3500)
    shard_faces = [f.index for f in obj.data.polygons if f.material_index in (0, 3)]
    shard_verts = {vi for fi in shard_faces for vi in obj.data.polygons[fi].vertices}
    rest = [v.co.z for v in obj.data.vertices if v.index not in shard_verts]
    # The shards stand on the snow: they shrink down towards it.
    base_z = sorted(rest)[int(len(rest) * 0.9)] if rest else 0.0
    full = {vi: obj.data.vertices[vi].co.copy() for vi in shard_verts}
    for k, size in enumerate((0.0, 0.35, 0.7, 1.0)):
        f = 0.15 + 0.85 * size
        for vi, co in full.items():
            z = base_z + max(co.z - base_z, 0.0) * f
            obj.data.vertices[vi].co = Vector((co.x, co.y, min(co.z, z)))
        obj.data.update()
        bake(f"crystal-{k}", [obj])


MODELS = {"crystal": crystal}

if __name__ == "__main__":
    want = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else list(MODELS)
    for name in want:
        MODELS[name]()
